    assertEquals(TEST_HIVE_METASTORE_URI2, jobConf.get(HCAT_METASTORE_URI));
    assertNull(jobConf.get(HIVE_METASTORE_PRINCIPAL));
    assertNull(jobConf.get(HIVE_METASTORE_URI));
